<?php
declare(strict_types=1);
foreach(['Product','Category','CatalogService','CatalogRepository'] as $f)require_once __DIR__."/../src/$f.php";
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$c=(new CatalogRepository())->load(__DIR__.'/../dataset/products.json',__DIR__.'/../dataset/categories.json');
$f=['q'=>trim((string)($_GET['q']??'')),'category'=>(string)($_GET['category']??''),'min'=>(string)($_GET['min']??''),'max'=>(string)($_GET['max']??''),'active'=>isset($_GET['active'])];
$errors=[];foreach(['min','max'] as $k)if($f[$k]!==''&&(!is_numeric($f[$k])||(float)$f[$k]<0)){$errors[]='Цена должна быть неотрицательным числом.';$f[$k]='';}
if($f['min']!==''&&$f['max']!==''&&(float)$f['min']>(float)$f['max'])$errors[]='Цена от не может превышать цену до.';
$items=$c->products($f);
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Каталог ТРПО 05</title><style>
body{margin:0;background:#f3f5fa;color:#172033;font:16px system-ui}header{background:#172554;color:white;padding:24px max(20px,calc((100% - 1000px)/2))}main{max-width:1000px;margin:28px auto;padding:0 18px}.panel,.card{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin-bottom:16px}.filters,.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}label{display:block}input,select{padding:9px;border:1px solid #cbd5e1;border-radius:8px;width:100%;box-sizing:border-box}button{background:#315efb;color:white;border:0;padding:10px 14px;border-radius:8px}.price{font-size:1.4rem;font-weight:bold}.muted{color:#64748b}.tag{background:#e9efff;padding:4px 8px;border-radius:20px}@media(max-width:650px){.filters,.cards{grid-template-columns:1fr}}</style></head><body><header><h1>Каталог товаров</h1>Практическая работа №05 · ООП</header><main><p class="muted">Солопов Антон · ЭПБО-01-25 · Активных товаров: <?=$c->countActive()?></p><section class="panel"><h2>Фильтры</h2><?php foreach($errors as $x):?><p><?=e($x)?></p><?php endforeach;?><form method="get"><div class="filters"><label>Название<input name="q" value="<?=e($f['q'])?>"></label><label>Категория<select name="category"><option value="">Все</option><?php foreach($c->categories() as $cat):?><option value="<?=$cat->id()?>" <?=$f['category']==$cat->id()?'selected':''?>><?=e($cat->name())?></option><?php endforeach;?></select></label><label>Цена от<input name="min" type="number" min="0" step=".01" value="<?=e($f['min'])?>"></label><label>Цена до<input name="max" type="number" min="0" step=".01" value="<?=e($f['max'])?>"></label></div><p><label><input type="checkbox" name="active" style="width:auto" <?=$f['active']?'checked':''?>> Только активные</label></p><button>Применить</button> <a href="/">Сбросить</a></form></section><p>Найдено: <?=count($items)?></p><section class="cards"><?php foreach($items as $p):?><article class="card"><span class="tag"><?=$p->isActive()?'Активен':'Неактивен'?></span><h3><?=e($p->name())?></h3><p class="muted"><?=e($c->categoryName($p->categoryId()))?></p><p class="price"><?=number_format($p->price(),2,',',' ')?> ₽</p><small>ID <?=$p->id()?></small></article><?php endforeach;?></section><?php if(!$items):?><p>Нет товаров по выбранным условиям.</p><?php endif;?></main></body></html>